# ============================================================
# PASSWORD UTILITIES
# ============================================================
def verify_password(plain: str, stored: str) -> bool:
    try:
        return bcrypt.checkpw(plain.encode("utf-8"), stored.encode("utf-8"))
    except Exception:
        return plain == stored

def hash_password(plain: str) -> str:
    return bcrypt.hashpw(plain.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")

# ============================================================
# SUPABASE HELPERS
# ============================================================
def get_agent_by_email(email: str):
    try:
        res = supabase.table("agents").select("*").eq("email", email).execute()
        return res.data[0] if res.data else None
    except Exception as e:
        st.error(f"Database error: {e}")
        return None

def get_listings_for_agent(agent_id: str):
    try:
        res = (supabase.table("listings")
               .select("*")
               .eq("agent_id", agent_id)
               .order("created_at", desc=True)
               .limit(20)
               .execute())
        return res.data or []
    except Exception:
        return []

def save_listing(agent_id: str, title: str, content: str, property_type: str, location: str, price: str):
    try:
        supabase.table("listings").insert({
            "agent_id": agent_id,
            "title": title,
            "content": content,
            "property_type": property_type,
            "location": location,
            "price": price,
            "created_at": datetime.utcnow().isoformat()
        }).execute()
        return True
    except Exception as e:
        st.error(f"Save error: {e}")
        return False

def update_agent_profile(agent_id: str, fields: dict):
    try:
        supabase.table("agents").update(fields).eq("id", agent_id).execute()
        return True
    except Exception as e:
        st.error(f"Profile update error: {e}")
        return False

# ============================================================
# FACEBOOK
# ============================================================
def post_to_facebook(message: str) -> dict:
    if not FB_PAGE_TOKEN or not FB_PAGE_ID:
        return {"error": "Facebook credentials not configured"}
    try:
        url = f"https://graph.facebook.com/v25.0/{FB_PAGE_ID}/feed"
        payload = {
            "message": message + "\n\n#NestListPrestige #SingaporeProperty #GCB #LuxuryRealEstate",
            "access_token": FB_PAGE_TOKEN
        }
        r = requests.post(url, data=payload, timeout=15)
        return r.json()
    except Exception as e:
        return {"error": str(e)}

# ============================================================
# URA COMPLIANCE
# ============================================================
GCB_ZONES = [
    "nassim","white house","cluny","dalvey","swiss club","oei tiong ham",
    "victoria park","maryland","queen astrid","jesselton","binjai",
    "coronation","fordham","king albert","clementi","greenwood",
    "raffles park","first avenue","sixth avenue","watten","garlick",
    "olive road","yarwood","leedon","cornwall","chestnut","dunearn",
    "windsor","worcester","belmont","chee hoon","linden","margoliouth",
    "seton close","bishop gate","white house park","ridout","gallop"
]

def check_gcb_compliance(location, land_sqm, plot_width, storeys, plot_depth, site_cov, sg_citizen):
    loc = location.lower()
    in_zone = any(z in loc for z in GCB_ZONES)
    results = {
        "GCB Zone":       {"pass": in_zone,              "msg": "Recognised GCB zone" if in_zone else "Verify location with URA"},
        "Land Size":      {"pass": land_sqm >= 1400,     "msg": f"{land_sqm:.0f} sqm (min 1,400 sqm)"},
        "Plot Width":     {"pass": plot_width >= 18.5,   "msg": f"{plot_width:.1f} m (min 18.5 m)"},
        "Storeys":        {"pass": storeys <= 2,         "msg": f"{storeys} storeys (max 2 + attic)"},
        "Plot Depth":     {"pass": plot_depth >= 30,     "msg": f"{plot_depth:.1f} m (min 30 m)"},
        "Site Coverage":  {"pass": site_cov <= 40,       "msg": f"{site_cov:.1f}% (max 40%)"},
        "Singapore Citizen": {"pass": sg_citizen,        "msg": "Confirmed" if sg_citizen else "GCB ownership restricted to Singapore Citizens"},
    }
    results["_overall"] = "APPROVED" if all(v["pass"] for v in results.values()) else "PENDING REVIEW"
    return results

# ============================================================
# AI LISTING WRITER
# ============================================================
def write_listing(agent_name, agent_style, property_type, location, land_size, buildup, bedrooms, price, features):
    style_map = {
        "Formal":   "professional, precise, authoritative — suitable for ultra-high-net-worth buyers",
        "Warm":     "warm, personal, family-focused — emphasise lifestyle and community",
        "Bold":     "bold, aspirational, commanding — every sentence demands attention",
        "Jane Lee": "warm and conversational, family-focused. Signature phrase: Home is where the heart is"
    }
    style_desc = style_map.get(agent_style, style_map["Formal"])
    prompt = f"""You are writing a Singapore luxury property listing for NestList Prestige.
Agent: {agent_name} | Style: {style_desc}
Property: {property_type} at {location}
Land: {land_size} | Built-up: {buildup} | Beds: {bedrooms} | Price: {price}
Features: {features}

Write a compelling luxury listing (250-320 words):
1. Powerful headline in ALL CAPS (max 10 words)
2. Opening paragraph — evoke prestige and Singapore lifestyle
3. Property highlights — specific, vivid, believable
4. Location context — Singapore GCB/luxury market
5. Closing invitation

No emojis. No exclamation marks. Write with quiet confidence."""
    try:
        msg = claude.messages.create(
            model="claude-sonnet-4-5",
            max_tokens=800,
            messages=[{"role": "user", "content": prompt}]
        )
        return msg.content[0].text
    except Exception as e:
        return f"Error: {e}"

