def show_login():
    col1, col2, col3 = st.columns([1, 1.1, 1])
    with col2:
        st.markdown('<div class="login-wrap">', unsafe_allow_html=True)
        st.markdown(f'<div style="text-align:center"><img src="{LOGO_URI}" width="150" style="border-radius:4px;"></div>', unsafe_allow_html=True)
        st.markdown('<p class="login-title">NESTLIST PRESTIGE</p>', unsafe_allow_html=True)
        st.markdown('<p class="login-sub">Singapore Luxury Property Platform</p>', unsafe_allow_html=True)

        email    = st.text_input("Email Address", placeholder="your@email.com", key="login_email")
        password = st.text_input("Password", type="password", placeholder="Enter password", key="login_pw")

        st.markdown("<br>", unsafe_allow_html=True)
        if st.button("Sign In", use_container_width=True, key="login_btn"):
            if not email or not password:
                st.error("Please enter your email and password.")
            else:
                agent = get_agent_by_email(email.strip().lower())
                if agent and verify_password(password, agent.get("password_hash", "")):
                    st.session_state.logged_in = True
                    st.session_state.agent = agent
                    st.rerun()
                else:
                    st.error("Invalid credentials. Please try again.")

        st.markdown("""
        <p style="text-align:center;font-size:0.62rem;color:#2a3e2f;margin-top:2rem;letter-spacing:0.1em;">
        SMARTER LISTINGS. BETTER RESULTS.<br>NestList Pte Ltd · Singapore 2026
        </p>
        """, unsafe_allow_html=True)
        st.markdown('</div>', unsafe_allow_html=True)

