# PAGE: NEW LISTING
# ============================================================
def page_new_listing():
    agent      = st.session_state.agent or {}
    agent_id   = agent.get("id", "")
    agent_name = agent.get("name", "Agent")

    st.markdown("""
    <div class="nl-header">
        <div class="nl-header-left"><h1><span>NEW</span> LISTING</h1><p>Create a luxury property listing</p></div>
    </div>
    """, unsafe_allow_html=True)

    col1, col2 = st.columns(2)
    with col1:
        property_type = st.selectbox("Property Type", ["GCB (Good Class Bungalow)","Landed — Detached","Landed — Semi-Detached","Landed — Terrace","Penthouse","Luxury Condo"])
        location      = st.text_input("Location / District", placeholder="e.g. Nassim Road, District 10")
        land_size     = st.text_input("Land Size", placeholder="e.g. 2,000 sqm / 21,528 sqft")
        buildup       = st.text_input("Built-up Area", placeholder="e.g. 850 sqm")
    with col2:
        bedrooms = st.text_input("Bedrooms / Configuration", placeholder="e.g. 6 bedrooms + study + lift")
        price    = st.text_input("Asking Price", placeholder="e.g. SGD 28,000,000")
        features = st.text_area("Key Features", placeholder="Infinity pool, wine cellar, home theatre, smart home...", height=105)
        style    = st.selectbox("Writing Style", ["Formal","Warm","Bold","Jane Lee"])

    is_gcb = "GCB" in property_type

    if is_gcb:
        st.markdown("---")
        st.markdown('<div class="section-label">URA GCB Compliance Check</div>', unsafe_allow_html=True)
        c1, c2, c3 = st.columns(3)
        with c1:
            land_sqm   = st.number_input("Land Size (sqm)", min_value=0.0, value=1400.0, step=10.0)
            plot_width = st.number_input("Plot Width (m)", min_value=0.0, value=18.5, step=0.5)
        with c2:
            storeys    = st.number_input("Storeys", min_value=1, max_value=5, value=2)
            plot_depth = st.number_input("Plot Depth (m)", min_value=0.0, value=30.0, step=1.0)
        with c3:
            site_cov   = st.number_input("Site Coverage (%)", min_value=0.0, max_value=100.0, value=35.0)
            sg_citizen = st.checkbox("Buyer is a Singapore Citizen")

    declaration = st.checkbox("I declare the information is accurate and I accept responsibility for URA compliance.")

    if st.button("Generate Listing", type="primary"):
        if not declaration:
            st.warning("Please tick the declaration before proceeding.")
        elif not location or not price:
            st.warning("Please fill in Location and Asking Price at minimum.")
        else:
            compliance_ok = True
            if is_gcb:
                results = check_gcb_compliance(location, land_sqm, plot_width, storeys, plot_depth, site_cov, sg_citizen)
                overall = results.pop("_overall")
                st.markdown("**Compliance Check Results:**")
                for key, val in results.items():
                    icon = "✅" if val["pass"] else "⚠️"
                    cls  = "check-pass" if val["pass"] else "check-fail"
                    st.markdown(f'<p class="{cls}">{icon} {key}: {val["msg"]}</p>', unsafe_allow_html=True)
                colour = "#6dbd6d" if overall == "APPROVED" else "#e07070"
                st.markdown(f'<p style="font-weight:600;color:{colour};font-size:0.9rem;">Overall: {overall}</p>', unsafe_allow_html=True)
                if overall != "APPROVED":
                    compliance_ok = False

            if compliance_ok:
                with st.spinner("NestList AI is writing your listing..."):
                    listing_text = write_listing(agent_name, style, property_type, location, land_size, buildup, bedrooms, price, features)

                st.markdown("---")
                st.markdown('<div class="section-label">Your Generated Listing</div>', unsafe_allow_html=True)
                st.text_area("", value=listing_text, height=360)

                title = f"{location} — {property_type}"
                if save_listing(agent_id, title, listing_text, property_type, location, price):
                    st.success("Listing saved to your portfolio.")

                if st.button("Post to Facebook"):
                    result = post_to_facebook(f"{title}\n\nAsking: {price}\n\n{listing_text[:800]}")
                    if "id" in result:
                        st.success("Posted to Facebook!")
                    else:
                        st.error(f"Facebook error: {result.get('error','Unknown')}")

                st.markdown('<p style="font-size:0.62rem;color:#3a4e3f;font-style:italic;margin-top:0.8rem;">⚠ AI-generated content. Verify all details before publishing. Compliance with URA and CEA regulations is the agent\'s responsibility.</p>', unsafe_allow_html=True)

