def page_my_listings():
    st.markdown("""
    <div class="nl-header">
        <div class="nl-header-left"><h1><span>MY</span> LISTINGS</h1><p>Your property portfolio</p></div>
    </div>
    """, unsafe_allow_html=True)

    agent_id = (st.session_state.agent or {}).get("id", "")
    listings = get_listings_for_agent(agent_id)

    if not listings:
        st.markdown('<p style="color:#3a5a42;font-size:0.85rem;">No listings yet. Go to New Listing to create your first.</p>', unsafe_allow_html=True)
        return

    for l in listings:
        with st.expander(f"{l.get('location','Untitled')} · {l.get('price','')}"):
            st.markdown(f"**Type:** {l.get('property_type','')}  |  **Price:** {l.get('price','')}")
            st.text_area("Listing", value=l.get("content",""), height=200, key=f"lt_{l.get('id','')}")
            if st.button("Post to Facebook", key=f"fb_{l.get('id','')}"):
                msg    = f"{l.get('location','')} — {l.get('property_type','')}\nAsking: {l.get('price','')}\n\n{l.get('content','')[:800]}"
                result = post_to_facebook(msg)
                if "id" in result:
                    st.success("Posted!")
                else:
                    st.error(f"Error: {result.get('error','Unknown')}")

