# MAIN ROUTER
# ============================================================
def main():
    inject_css()

    if not st.session_state.logged_in:
        show_login()
        return

    # Handle nav from quick action buttons
    if "_nav" in st.session_state:
        target = st.session_state.pop("_nav")
        st.session_state["_forced_page"] = target

    page = show_sidebar()

    if "_forced_page" in st.session_state:
        page = st.session_state.pop("_forced_page")

    if page == "Dashboard":      page_dashboard()
    elif page == "New Listing":  page_new_listing()
    elif page == "My Listings":  page_my_listings()
    elif page == "Enquiries":    page_enquiries()
    elif page == "My Profile":   page_my_profile()
    elif page == "Billing":      page_billing()

if __name__ == "__main__":
    main()
